        }

        openPRs = isScmForm
            ? scmOrWorkspace.listPrs('open')
            : github_list_prs({ workspace: scmOrWorkspace, repository: repositoryOrTicketKey, state: 'open' });
        console.log('Found', openPRs.length, 'open PRs');

        var normalizedKey = _normalizeForMatch(ticketKey);
