        } catch (gitError) {
            console.error('Git operations failed:', gitError);
            var resume = tryResumeAgent({
                ticketKey: ticketKey,
                customParams: _customParams,
                section: 'postAction',
                stage: 'rework_git_operations',
                error: gitError.toString()
            });
            if (resume.attempted) {
