        var pipelines = (parsed && parsed.value) ? parsed.value : (Array.isArray(parsed) ? parsed : []);
        var name = String(workflowIdentifier).toLowerCase();
        var match = pipelines.find(function(p) {
            return p.name && p.name.toLowerCase() === name;
