        var nonBlockingGateWarningBlock = '';
        if (nonBlockingGateWarnings.length > 0) {
            var warningLines = nonBlockingGateWarnings.map(function(f) {
                return '- **' + f.name + '**: ' + String(f.error).substring(0, 500);
            });
